// Prepare photo URLs for batch processing
const inputData = $input.first().json;

// Extract data from webhook
const propertyId = inputData.property_id;
const propertyType = inputData.property_type || 'house';
const photos = inputData.photos || [];

if (!propertyId || photos.length === 0) {
  throw new Error('Missing required fields: property_id and photos array');
}

// Map each photo to include property context
const preparedPhotos = photos.map((photo, index) => ({
  json: {
    property_id: propertyId,
    property_type: propertyType,
    photo_url: photo.url,
    photo_index: index,
    filename: photo.filename || `photo_${index}.jpg`
  }
}));

return preparedPhotos;

// Prepare Groq prompt for each photo
const photo = $input.first().json;

const promptTemplate = `Analyze this South African property photo and extract detailed information.

Photo URL: ${photo.photo_url}
Property Type: ${photo.property_type}

Analyze carefully and return ONLY valid JSON with this exact structure:
{
  "room_type": "kitchen|bedroom|bathroom|lounge|dining|exterior|garden|garage|other",
  "features_visible": [
    "pool",
    "garage", 
    "garden",
    "sea_view",
    "mountain_view",
    "modern_kitchen",
    "built_in_cupboards",
    "fireplace",
    "air_conditioning",
    "balcony",
    "patio",
    "security_gate",
    "alarm",
    "solar_panels",
    "borehole"
  ],
  "condition": "excellent|good|fair|needs_renovation",
  "style": "modern|traditional|minimalist|luxury|rustic",
  "photo_quality": {
    "is_blurry": true|false,
    "is_dark": true|false,
    "is_well_framed": true|false,
    "quality_score": 1-10
  },
  "is_primary_photo_candidate": true|false,
  "confidence": 0.0-1.0
}

Important notes:
- For room_type, be specific (e.g., 'kitchen' not just 'room')
- features_visible should only include features actually visible
- Consider South African property features like boreholes, solar panels, security
- photo_quality.quality_score: 8-10 = professional, 5-7 = acceptable, 1-4 = poor
- is_primary_photo_candidate: true if this would make a good main/listing photo
- confidence: your confidence in this assessment (0.0-1.0)`;

return {
  json: {
    ...photo,
    prompt: promptTemplate
  }
};

// Parse Groq AI response
const input = $input.first().json;
const photo = input.photo_data;
const groqResponse = input.groq_response;

try {
  // Extract the AI content from Groq response
  const aiContent = groqResponse.choices?.[0]?.message?.content;
  if (!aiContent) {
    throw new Error('No content in Groq response');
  }

  // Parse the JSON response
  const analysis = JSON.parse(aiContent);

  // Build the tag record
  const tagRecord = {
    property_id: photo.property_id,
    photo_url: photo.photo_url,
    photo_index: photo.photo_index,
    room_type: analysis.room_type || 'other',
    features_visible: analysis.features_visible || [],
    condition: analysis.condition || 'unknown',
    style: analysis.style || 'unknown',
    photo_quality: {
      is_blurry: analysis.photo_quality?.is_blurry || false,
      is_dark: analysis.photo_quality?.is_dark || false,
      is_well_framed: analysis.photo_quality?.is_well_framed || false,
      quality_score: analysis.photo_quality?.quality_score || 5
    },
    is_primary_candidate: analysis.is_primary_photo_candidate || false,
    confidence: analysis.confidence || 0.5,
    tagged_at: new Date().toISOString()
  };

  return {
    json: tagRecord
  };
} catch (error) {
  // Return error record for failed analysis
  return {
    json: {
      property_id: photo.property_id,
      photo_url: photo.photo_url,
      photo_index: photo.photo_index,
      room_type: 'error',
      features_visible: [],
      condition: 'unknown',
      style: 'unknown',
      photo_quality: {
        is_blurry: false,
        is_dark: false,
        is_well_framed: false,
        quality_score: 0
      },
      is_primary_candidate: false,
      confidence: 0,
      error: error.message,
      tagged_at: new Date().toISOString()
    }
  };
}

// Aggregate all photo tags and generate recommendations
const allTags = $input.all()[0].json;

// Collect tags from all items
const tags = $input.all().map(item => item.json);

// Determine property_id (should be same for all)
const propertyId = tags[0]?.property_id;

// Find primary photo candidates (sorted by quality score and confidence)
const primaryCandidates = tags
  .filter(t => t.is_primary_candidate && t.photo_quality?.quality_score >= 7)
  .sort((a, b) => {
    const scoreA = (a.photo_quality?.quality_score || 0) * (a.confidence || 0);
    const scoreB = (b.photo_quality?.quality_score || 0) * (b.confidence || 0);
    return scoreB - scoreA;
  });

const recommendedPrimary = primaryCandidates[0] || null;

// Check for missing essential photo types
const essentialRoomTypes = ['kitchen', 'bedroom', 'bathroom', 'lounge', 'exterior'];
const foundRoomTypes = new Set(tags.map(t => t.room_type).filter(Boolean));
const missingPhotos = essentialRoomTypes.filter(type => !foundRoomTypes.has(type));

// Count photos by room type
const roomTypeCounts = {};
tags.forEach(t => {
  const rt = t.room_type || 'unknown';
  roomTypeCounts[rt] = (roomTypeCounts[rt] || 0) + 1;
});

// Collect all detected features
const allFeatures = new Set();
tags.forEach(t => {
  if (Array.isArray(t.features_visible)) {
    t.features_visible.forEach(f => allFeatures.add(f));
  }
});

// Identify quality issues
const qualityIssues = tags.filter(t => 
  t.photo_quality?.is_blurry || 
  t.photo_quality?.is_dark || 
  (t.photo_quality?.quality_score || 10) < 5
);

// Determine overall property style (most common)
const styleCounts = {};
tags.forEach(t => {
  if (t.style && t.style !== 'unknown') {
    styleCounts[t.style] = (styleCounts[t.style] || 0) + 1;
  }
});
const dominantStyle = Object.entries(styleCounts)
  .sort((a, b) => b[1] - a[1])[0]?.[0] || 'unknown';

// Overall condition (most common non-unknown)
const conditionCounts = {};
tags.forEach(t => {
  if (t.condition && t.condition !== 'unknown') {
    conditionCounts[t.condition] = (conditionCounts[t.condition] || 0) + 1;
  }
});
const overallCondition = Object.entries(conditionCounts)
  .sort((a, b) => b[1] - a[1])[0]?.[0] || 'unknown';

// Calculate average confidence
const avgConfidence = tags.reduce((sum, t) => sum + (t.confidence || 0), 0) / tags.length;

return {
  json: {
    property_id: propertyId,
    total_photos: tags.length,
    tags: tags,
    recommendations: {
      primary_photo: recommendedPrimary ? {
        photo_url: recommendedPrimary.photo_url,
        room_type: recommendedPrimary.room_type,
        quality_score: recommendedPrimary.photo_quality?.quality_score,
        reason: `Best quality (${recommendedPrimary.photo_quality?.quality_score}/10) with high confidence (${(recommendedPrimary.confidence * 100).toFixed(0)}%)`
      } : null,
      missing_photos: missingPhotos,
      missing_photos_warnings: missingPhotos.length > 0 ? 
        missingPhotos.map(type => `Missing ${type} photo - consider adding for better listing performance`) : [],
      quality_issues: qualityIssues.map(t => ({
        photo_url: t.photo_url,
        issues: [
          ...(t.photo_quality?.is_blurry ? ['blurry'] : []),
          ...(t.photo_quality?.is_dark ? ['dark'] : []),
          ...(t.photo_quality?.quality_score < 5 ? ['low_quality'] : [])
        ]
      }))
    },
    analysis_summary: {
      room_type_counts: roomTypeCounts,
      detected_features: Array.from(allFeatures),
      dominant_style: dominantStyle,
      overall_condition: overallCondition,
      average_confidence: parseFloat(avgConfidence.toFixed(2)),
      photos_with_quality_issues: qualityIssues.length
    },
    generated_at: new Date().toISOString()
  }
};

// Prepare data for Groq request
const photo = $input.first().json;

return {
  json: {
    photo_data: photo,
    groq_response: $input.first().json
  }
};
